CREATE FUNCTION "dream_guard_events_no_delete"() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'events is append-only';
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "events_no_delete"
BEFORE DELETE ON "events"
FOR EACH ROW EXECUTE FUNCTION "dream_guard_events_no_delete"();

CREATE FUNCTION "dream_guard_events_no_update"() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'events is append-only';
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "events_no_update"
BEFORE UPDATE ON "events"
FOR EACH ROW EXECUTE FUNCTION "dream_guard_events_no_update"();

