CREATE FUNCTION "dream_guard_agent_sessions_immutable_binding"() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF OLD.agent_session_id IS DISTINCT FROM NEW.agent_session_id
    OR OLD.workflow_run_id IS DISTINCT FROM NEW.workflow_run_id
    OR OLD.runtime_load_receipt_id IS DISTINCT FROM NEW.runtime_load_receipt_id
    OR OLD.runtime_environment_id IS DISTINCT FROM NEW.runtime_environment_id
    OR OLD.runtime_pool_id IS DISTINCT FROM NEW.runtime_pool_id
    OR OLD.distribution_mode IS DISTINCT FROM NEW.distribution_mode
    OR OLD.runtime_node_id IS DISTINCT FROM NEW.runtime_node_id
    OR OLD.artifact_set_hash IS DISTINCT FROM NEW.artifact_set_hash
    OR OLD.policy_revision IS DISTINCT FROM NEW.policy_revision
    OR OLD.deployment_tier IS DISTINCT FROM NEW.deployment_tier
    OR OLD.runtime_plugin_lock_id IS DISTINCT FROM NEW.runtime_plugin_lock_id
    OR OLD.runtime_plugin_lock_digest IS DISTINCT FROM NEW.runtime_plugin_lock_digest
    OR OLD.settings_json IS DISTINCT FROM NEW.settings_json
    OR OLD.settings_hash IS DISTINCT FROM NEW.settings_hash
    OR OLD.plugin_set_hash IS DISTINCT FROM NEW.plugin_set_hash
    OR OLD.session_request_key IS DISTINCT FROM NEW.session_request_key
    OR OLD.attempt_number IS DISTINCT FROM NEW.attempt_number
    OR OLD.created_at IS DISTINCT FROM NEW.created_at THEN
    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'agent session binding is immutable';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "agent_sessions_immutable_binding"
BEFORE UPDATE ON "agent_sessions"
FOR EACH ROW EXECUTE FUNCTION "dream_guard_agent_sessions_immutable_binding"();

CREATE FUNCTION "dream_guard_agent_sessions_lifecycle_insert_guard"() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.status != 'creating'
    OR NEW.started_at IS NOT NULL
    OR NEW.terminated_at IS NOT NULL
    OR NEW.error_code IS NOT NULL
    OR NEW.termination_reason_code IS NOT NULL
    OR NEW.lease_expires_at IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'new agent session must start with a creating lease';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "agent_sessions_lifecycle_insert_guard"
BEFORE INSERT ON "agent_sessions"
FOR EACH ROW EXECUTE FUNCTION "dream_guard_agent_sessions_lifecycle_insert_guard"();

CREATE FUNCTION "dream_guard_agent_sessions_lifecycle_update_guard"() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF (NEW.status = 'active' AND (
    NEW.started_at IS NULL OR NEW.terminated_at IS NOT NULL
    OR NEW.error_code IS NOT NULL OR NEW.termination_reason_code IS NOT NULL
    ))
    OR (NEW.status = 'terminated' AND (
    NEW.started_at IS NULL OR NEW.terminated_at IS NULL
    OR NEW.error_code IS NOT NULL OR NEW.termination_reason_code IS NULL
    ))
    OR (NEW.status = 'failed' AND (
    NEW.terminated_at IS NULL OR NEW.error_code IS NULL
    OR NEW.termination_reason_code IS NULL
    )) THEN
    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'agent session lifecycle fields are inconsistent';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "agent_sessions_lifecycle_update_guard"
BEFORE UPDATE ON "agent_sessions"
FOR EACH ROW EXECUTE FUNCTION "dream_guard_agent_sessions_lifecycle_update_guard"();

CREATE FUNCTION "dream_guard_agent_sessions_status_guard"() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status
    AND NOT (
    (OLD.status = 'creating' AND NEW.status IN ('active', 'failed'))
    OR (OLD.status = 'active' AND NEW.status IN ('terminated', 'failed'))
    ) THEN
    RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'agent session transition is not allowed';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "agent_sessions_status_guard"
BEFORE UPDATE OF STATUS ON "agent_sessions"
FOR EACH ROW EXECUTE FUNCTION "dream_guard_agent_sessions_status_guard"();

