CREATE TABLE "resource_connectors" (
  "id" TEXT,
  "user_id" BIGINT NOT NULL,
  "name" TEXT NOT NULL,
  "platform" TEXT NOT NULL,
  "auth_status" TEXT NOT NULL DEFAULT 'pending',
  "config_json" TEXT NOT NULL DEFAULT '{}',
  "current_snapshot_version" TEXT,
  "current_source_revision" TEXT,
  "current_sync_cursor" TEXT,
  "last_synced_at" TIMESTAMPTZ,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
  "updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT "pk_resource_connectors" PRIMARY KEY ("id"),
  CONSTRAINT "fk_resource_connectors_user_id_users" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE RESTRICT
);

CREATE TABLE "connector_resources" (
  "id" TEXT,
  "connector_id" TEXT NOT NULL,
  "resource_type" TEXT NOT NULL,
  "external_id" TEXT,
  "title" TEXT NOT NULL,
  "metadata_json" TEXT NOT NULL DEFAULT '{}',
  "sync_status" TEXT NOT NULL DEFAULT 'synced',
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
  "updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT "pk_connector_resources" PRIMARY KEY ("id"),
  CONSTRAINT "uq_connector_resources_connector_id_resource_type_external_id" UNIQUE ("connector_id", "resource_type", "external_id"),
  CONSTRAINT "fk_connector_resources_connector_id_resource_connectors" FOREIGN KEY ("connector_id") REFERENCES "resource_connectors" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);

CREATE TABLE "connector_resource_pages" (
  "id" TEXT,
  "resource_id" TEXT NOT NULL,
  "page_id" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "last_edited" TIMESTAMPTZ,
  "properties_json" TEXT,
  "page_json" TEXT,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
  "updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT "pk_connector_resource_pages" PRIMARY KEY ("id"),
  CONSTRAINT "uq_connector_resource_pages_resource_id_page_id" UNIQUE ("resource_id", "page_id"),
  CONSTRAINT "fk_connector_resource_pages_resource_id_connector_resources" FOREIGN KEY ("resource_id") REFERENCES "connector_resources" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);

CREATE TABLE "connector_snapshots" (
  "id" TEXT,
  "connector_id" TEXT NOT NULL,
  "snapshot_version" TEXT NOT NULL,
  "source_revision" TEXT NOT NULL,
  "sync_cursor" TEXT NOT NULL,
  "fetched_at" TIMESTAMPTZ NOT NULL,
  "state" TEXT NOT NULL DEFAULT 'snapshot_ready',
  "snapshot_json" TEXT NOT NULL,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
  "updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT "pk_connector_snapshots" PRIMARY KEY ("id"),
  CONSTRAINT "uq_connector_snapshots_connector_id_snapshot_version" UNIQUE ("connector_id", "snapshot_version"),
  CONSTRAINT "fk_connector_snapshots_connector_id_resource_connectors" FOREIGN KEY ("connector_id") REFERENCES "resource_connectors" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);

CREATE TABLE "connector_chat_threads" (
  "id" TEXT,
  "connector_id" TEXT NOT NULL,
  "thread_id" TEXT NOT NULL,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
  "updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT "pk_connector_chat_threads" PRIMARY KEY ("id"),
  CONSTRAINT "uq_connector_chat_threads_connector_id_thread_id" UNIQUE ("connector_id", "thread_id"),
  CONSTRAINT "fk_connector_chat_threads_connector_id_resource_connectors" FOREIGN KEY ("connector_id") REFERENCES "resource_connectors" ("id") ON UPDATE NO ACTION ON DELETE CASCADE
);

CREATE INDEX idx_resource_connectors_user_updated ON resource_connectors(user_id, updated_at DESC NULLS LAST);

CREATE INDEX idx_connector_resources_connector ON connector_resources(connector_id, resource_type, updated_at DESC NULLS LAST);

CREATE INDEX idx_connector_resource_pages_resource ON connector_resource_pages(resource_id, last_edited DESC NULLS LAST);

CREATE INDEX idx_connector_snapshots_connector ON connector_snapshots(connector_id, created_at DESC NULLS LAST);

CREATE INDEX idx_connector_chat_threads_connector ON connector_chat_threads(connector_id, updated_at DESC NULLS LAST);
